 const guard="EXISTS (SELECT 1 FROM records WHERE id=? AND kind='project' AND data=?) AND NOT EXISTS (SELECT 1 FROM jobs WHERE (project_id=? OR json_extract(payload,'$.sourceProjectId')=?) AND (status IN ('queued','running','applying','rolling back') OR json_extract(result,'$.workerAssignment.expiresAt')>?)) AND NOT EXISTS (SELECT 1 FROM records WHERE project_id=? AND ((kind='exposure' AND status IN ('active','reconciling','quarantined')) OR (kind='repo_audit' AND status='active')))";
