async function reconcileFindings(projectId:string,analysis:ReturnType<typeof analyze>,jobId:string,status:string,projectData:string,now:string){
 const existing=(await list()).filter(r=>r.kind==='finding'&&r.projectId===projectId);const key=(f:any)=>f.title+'\n'+f.file;const current=new Map(analysis.findings.map(f=>[key(f),f]));const ops=[];
 const uninspectedSecurity=new Set(analysis.securityAnalysis.files.filter(f=>f.status!=='inspected-heuristic').map(f=>f.path));
 const guard="EXISTS (SELECT 1 FROM jobs WHERE id=? AND status=?) AND EXISTS (SELECT 1 FROM records WHERE id=? AND data=?)";
 for(const old of existing){if(old.data.category==='Security'&&uninspectedSecurity.has(old.data.file))continue;const found=current.get(key(old.data));if(found){current.delete(key(old.data));const nextStatus=old.data.snapshotResolved?'open':old.status;ops.push(db().prepare("UPDATE records SET status=?,data=?,updated_at=? WHERE id=? AND "+guard).bind(nextStatus,JSON.stringify({...found,status:nextStatus}),now,old.id,jobId,status,projectId,projectData));}else{ops.push(db().prepare("UPDATE records SET status='resolved',data=?,updated_at=? WHERE id=? AND "+guard).bind(JSON.stringify({...old.data,status:'resolved',snapshotResolved:true,verification:'Absent from current rule-based snapshot analysis; not production verification'}),now,old.id,jobId,status,projectId,projectData));}}
 for(const f of current.values()){const r=record('finding',f.title,f,projectId,'open');ops.push(db().prepare("INSERT INTO records(id,kind,title,project_id,status,data,created_at,updated_at) SELECT ?,?,?,?,?,?,?,? WHERE "+guard).bind(r.id,r.kind,r.title,r.projectId,r.status,JSON.stringify(r.data),now,now,jobId,status,projectId,projectData));}return ops;
}
