   db().prepare("INSERT INTO records(id,kind,title,project_id,status,data,created_at,updated_at) SELECT ?,?,?,?,?,?,?,? WHERE "+accepted).bind(audit.id,audit.kind,audit.title,audit.projectId,audit.status,JSON.stringify(audit.data),now,now,raw.id,outcome,recoveryId)
